        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if adjacency matrix
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        # Convert to adjacency list
        adj_list = []
        for i in range(n):
            neighbors = []
            row = adj[i]
            for j in range(n):
                if row[j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj
        # Ensure it's a list of lists
        for i in range(n):
            if not isinstance(adj_list[i], list):
                adj_list[i] = list(adj_list[i])

