    degrees = [len(adj_list[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if coloring[v] == cu:
                    return False
        return True

    # DSATUR algorithm
    def dsatur():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = len(saturation[v])
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)

            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break: max degree in uncolored subgraph
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    # Count uncolored neighbors
