                    for nb in adj_list[v]:
                        if nb in uncolored:
                            deg_in_uncolored += 1
                    if deg_in_uncolored > max_deg:
                        max_deg = deg_in_uncolored
                        deg_candidates = [v]
                    elif deg_in_uncolored == max_deg:
                        deg_candidates.append(v)
                if len(deg_candidates) == 1:
                    v = deg_candidates[0]
                else:
                    v = random.choice(deg_candidates)

            # Find smallest available color
            used = saturation[v]
            c = 0
