                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    saturation[nb].add(c)

        return color

    # Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        color = [-1] * n
        for v in order:
            used = set()
            for nb in adj_list[v]:
