            while c in used:
                c += 1
            color[v] = c
        return color

    # Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        deg = degrees[:]  # current degree in remaining graph
        order = []
        # Bucket sort for efficiency
