            while i < len(buckets) and not buckets[i]:
                i += 1
            if i >= len(buckets):
                # Should not happen
                v = next(iter(remaining))
                remaining.remove(v)
                order.append(v)
                continue
            v = buckets[i].pop()
            if v not in remaining:
                # Find another
                while buckets[i] and (v not in remaining):
                    v = buckets[i].pop()
                if v not in remaining:
                    i += 1
                    while i < len(buckets) and not buckets[i]:
                        i += 1
                    if i >= len(buckets):
                        v = next(iter(remaining))
                        remaining.remove(v)
                        order.append(v)
                        continue
                    v = buckets[i].pop()
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    old_deg = deg[nb]
