            S = {v1}
            # Partition uncolored \ {v1} into U and W
            U = set()
            W = set()
            for v in uncolored:
                if v == v1:
                    continue
                adjacent_to_S = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(v)
                else:
                    U.add(v)

            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                tie_break_deg = float('inf')
                for u in U:
                    score = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    if score > best_score or (score == best_score and deg_in_U < tie_break_deg):
                        best_score = score
                        tie_break_deg = deg_in_U
                        best_u = u
                if best_u == -1:
