                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to all in S
            for v in S:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Kempe chain swap for color class elimination
    def kempe_swap(coloring, k):
        # Try to eliminate color k
        # Find vertices with color k
        color_k_vertices = [v for v in range(n) if coloring[v] == k]
        if not color_k_vertices:
            return coloring, True  # already eliminated

