            for nb in adj_list[v]:
                if coloring[nb] < k:
                    used_by_neighbors.add(coloring[nb])
            for c in range(k):
                if c not in used_by_neighbors:
                    # Move v to color c
                    coloring[v] = c
                    break
            else:
                # Direct move not possible, try Kempe chains
                for c in range(k):
                    # Check if v can be swapped via Kempe chain (v, c)
                    # We'll try to find the Kempe chain component of v in colors {k, c}
                    # and see if we can swap without pulling any vertex into color k
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for nb in adj_list[node]:
                            if nb not in visited and (coloring[nb] == k or coloring[nb] == c):
                                visited.add(nb)
                                queue.append(nb)
                    # Check if any neighbor of the component has color c (would cause conflict if swapped)
                    has_conflict = False
                    for node in component:
                        for nb in adj_list[node]:
                            if coloring[nb] == c and nb not in component:
                                has_conflict = True
                                break
                        if has_conflict:
                            break
                    if not has_conflict:
                        # Perform swap: k <-> c in component
                        for node in component:
                            if coloring[node] == k:
                                coloring[node] = c
                            else:  # must be c
                                coloring[node] = k
                        # After swap, v should be color c (since it was k)
                        break
                else:
                    # Could not recolor v with any Kempe chain
                    return coloring, False
        # If we get here, all color k vertices were recolored
        return coloring, True

    # Generate initial colorings
