    is_complete = True
    for i in range(n):
        if len(graph[i]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))
    # Welsh-Powell ordering (degree descending)
    order_wp = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
    # Greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in graph[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color
    color_wp = greedy_color(order_wp)
    k_wp = max(color_wp) + 1 if n > 0 else 0
    # DSATUR with optimized saturation update and tie-breaking
    color_ds = [-1] * n
    sat = [0] * n
    uncolored = set(range(n))
    # Precompute neighbor lists for speed
    neighbors = graph
    # Helper to update saturation of a vertex
    def update_sat(v):
        if color_ds[v] == -1:
            seen = set()
            for u in neighbors[v]:
                if color_ds[u] != -1:
                    seen.add(color_ds[u])
            sat[v] = len(seen)
    for _ in range(n):
        v = -1
        max_sat = -1
        max_deg = -1
        for u in uncolored:
            deg_u = len([w for w in neighbors[u] if w in uncolored])
            if sat[u] > max_sat or (sat[u] == max_sat and deg_u > max_deg):
                max_sat = sat[u]
                max_deg = deg_u
                v = u
            elif sat[u] == max_sat and deg_u == max_deg:
                if random.random() < 0.5:
                    v = u
        if v == -1:
            v = next(iter(uncolored))
        used = [False] * n
        for u in neighbors[v]:
            if color_ds[u] != -1:
                used[color_ds[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color_ds[v] = c
        uncolored.remove(v)
        for u in neighbors[v]:
            if color_ds[u] == -1:
                update_sat(u)
    k_ds = max(color_ds) + 1 if n > 0 else 0
    # RLF (Recursive Largest First) with optimized set operations
    color_rlf = [-1] * n
    uncolored_rlf = set(range(n))
    color_idx = 0
    while uncolored_rlf:
        S = []
        v = max(uncolored_rlf, key=lambda x: len([w for w in neighbors[x] if w in uncolored_rlf]))
        S.append(v)
        U = {u for u in uncolored_rlf if u not in S and all(u not in neighbors[w] for w in S)}
        W = {u for u in uncolored_rlf if u not in S and u not in U}
        while U:
            u_star = -1
            max_nw = -1
            min_deg_u = float('inf')
            for u in U:
                nw = len([w for w in neighbors[u] if w in W])
                deg_u = len([w for w in neighbors[u] if w in U])
                if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                    max_nw = nw
                    min_deg_u = deg_u
                    u_star = u
                elif nw == max_nw and deg_u == min_deg_u:
                    if random.random() < 0.5:
                        u_star = u
            if u_star == -1:
                u_star = next(iter(U))
            S.append(u_star)
            U.remove(u_star)
            for w in neighbors[u_star]:
                if w in U:
                    U.remove(w)
                    W.add(w)
        for v in S:
            color_rlf[v] = color_idx
            uncolored_rlf.remove(v)
        color_idx += 1
    k_rlf = color_idx
    # Choose the best coloring from DSATUR and RLF
    if k_ds <= k_rlf:
        best_color = color_ds
        best_k = k_ds
    else:
        best_color = color_rlf
        best_k = k_rlf
    # Kempe chain refinement with iterative improvement and time guard
    def kempe_swap(color_arr, k_current):
        changed = True
        iters = 0
        max_iters = 15  # Slightly increased for better convergence
        while changed and iters < max_iters and k_current > 0:
            changed = False
            iters += 1
            target = k_current - 1
            target_verts = [v for v in range(n) if color_arr[v] == target]
            random.shuffle(target_verts)
            for v in target_verts:
                # Try direct move to lower color
                for c in range(target):
                    if all(color_arr[u] != c for u in neighbors[v]):
                        color_arr[v] = c
                        changed = True
                        break
                else:
                    # Try Kempe chains
                    for c in range(target):
                        # BFS for Kempe chain (target, c)
                        visited = [False] * n
                        stack = [v]
                        visited[v] = True
                        component = []
                        while stack:
                            x = stack.pop()
                            component.append(x)
                            for y in neighbors[x]:
                                if not visited[y] and (color_arr[y] == target or color_arr[y] == c):
                                    visited[y] = True
                                    stack.append(y)
                        # Check for external color c neighbors (would cause conflict)
                        conflict = False
                        for x in component:
                            for y in neighbors[x]:
                                if color_arr[y] == c and y not in component:
                                    conflict = True
                                    break
                            if conflict:
                                break
                        if not conflict:
                            # Swap colors in component
                            for x in component:
                                if color_arr[x] == target:
                                    color_arr[x] = c
                                elif color_arr[x] == c:
                                    color_arr[x] = target
                            changed = True
                            break
                    else:
                        continue
                    break
            # After processing all target vertices, check if target color is still used
            if any(color_arr[v] == target for v in range(n)):
                break
            else:
                k_current -= 1
        return color_arr, k_current
    best_color, best_k = kempe_swap(best_color[:], best_k)
    return best_color
